const caseStudies=[
{id:'ionq',ticker:'IONQ',name:'아이온큐',type:'성장기업',title:'높은 성장률 다음에는 무엇을 볼까?',date:'2026년 2분기 · 2026.06.30 종료 · 08.05 발표',source:'https://www.sec.gov/Archives/edgar/data/1824920/000119312526335040/ionq-ex99_1.htm',sourceName:'IonQ 실적 발표 · SEC 제출 원문',metrics:[['분기 매출','$80.1M','8,010만 달러'],['전년 대비 매출 성장','287%','회사 발표 기준'],['연간 매출 전망','$280–290M','실적이 아닌 회사 가이던스']],fact:'회사는 2분기 매출과 함께 인수 및 기술 개발 진척을 발표했습니다. 성장률만 보고 기존 사업의 성장과 인수로 추가된 성장을 같은 것으로 취급하면 안 됩니다.',interpret:'학습 관점: 기술의 발전 → 고객의 유료 도입 → 매출 인식 → 현금 회수로 연결되는지 단계별로 검증합니다. 큰 시장 전망과 현재의 사업 성과는 구분합니다.',workedTitle:'성장률을 금액으로 되돌려 보기',worked:'발표된 287% 증가를 역산하면 전년 동기 매출은 약 80.1 ÷ 3.87 = 20.7M 달러입니다. 증가율이 높아도 출발 규모가 작을 수 있습니다. 반올림된 성장률의 역산값이므로 전년 공시 숫자와 대조해야 합니다.',checks:[['기존 사업과 인수 효과','매출 증가 중 기존 사업에서 나온 부분을 회사의 정의와 함께 확인합니다.'],['영업현금흐름과 자금 조달','순손실을 현금 소진액으로 대신 쓰지 않습니다. 현금흐름표와 인수 지출, 신규 발행 주식 수를 함께 봅니다.'],['기술 이정표와 상용화','회사 발표의 성능 기준과 유료 고객의 활용을 분리합니다. 계약·수주·매출은 같은 숫자가 아닙니다.']],risk:'기술 일정 지연, 상용화 속도, 자금 소요, 인수 통합을 점검할 질문으로 둡니다. 적자 구간에서는 PER 하나로 가격의 매력을 판단하기 어렵습니다.',next:'다음 실적에서 기존 사업 성장, 영업현금 유출, 주식 수 변화, 매출 전망 달성 근거를 확인하기.',q:'매출이 287% 늘었다면 확인할 다음 질문은?',options:['주가도 287% 오를까?','기존 사업 성장과 인수 효과, 현금흐름은 어떠한가?','성장률이 높으니 가격은 상관없을까?'],correct:1,answer:'성장의 출처와 현금 전환을 봐야 지속 가능성을 검토할 수 있습니다.'},
{id:'nvda',ticker:'NVDA',name:'엔비디아',type:'수익성 있는 성장기업',title:'매출 성장, 이익, 현금은 함께 가는가?',date:'FY2027 2분기 · 2026.07.26 종료 · 08.26 발표',source:'https://nvidianews.nvidia.com/news/nvidia-announces-financial-results-for-second-quarter-fiscal-2027',sourceName:'NVIDIA 공식 실적 발표',metrics:[['분기 매출','$96,221M','전년 동기 $46,743M'],['GAAP 영업이익','$63,734M','매출총이익과 구분'],['GAAP 매출총이익률','75.0%','영업이익률과 구분']],fact:'회계연도 FY2027의 분기이지만 종료일은 2026년 7월입니다. 달력연도와 회계연도를 혼동하지 말고 같은 기간의 수치를 비교하세요.',interpret:'학습 관점: 매출 성장만큼 수익성과 현금 회수의 지속성을 살펴봅니다. 고객의 투자 수요, 제품 전환, 경쟁이 향후 이익에 어떤 영향을 줄지 질문을 만듭니다.',workedTitle:'직접 계산한 영업이익률',worked:'63,734 ÷ 96,221 × 100 ≈ 66.2%. 이는 영업이익률입니다. 발표된 매출총이익률 75.0%와 다른 지표입니다. 매출원가 외 연구개발비·판매관리비 등을 반영하는 단계가 다릅니다.',checks:[['매출의 지속성','어느 사업과 고객군이 성장을 이끄는지 원문과 고객사의 실적 자료를 함께 봅니다.'],['수익과 현금의 차이','영업현금흐름과 매출채권·재고 변화의 원인을 확인합니다. 한 분기 차이만으로 회계 문제라고 단정하지 않습니다.'],['가격에 담긴 기대','현재 주가를 확인한 날짜와 EPS의 기준을 적습니다. 한 분기 EPS에 단순히 4를 곱한 값은 확정 연간 이익이 아닙니다.']],risk:'고객 투자 둔화, 경쟁 제품, 수출 제한, 공급 제약을 검토합니다. 실적이 좋아도 시장의 기대보다 낮으면 가격은 다른 방향으로 움직일 수 있습니다.',next:'다음 실적에서 매출 성장과 이익률, 현금 전환을 비교하고 현재 가격의 이익 가정을 다시 확인하기.',q:'63,734 ÷ 96,221로 계산한 66.2%는?',options:['매출총이익률','영업이익률','주가 수익률'],correct:1,answer:'분자에 영업이익을 사용했으므로 영업이익률입니다. 회사가 발표한 75.0%는 매출총이익률입니다.'},
{id:'voo',ticker:'VOO',name:'S&P 500 ETF',type:'지수 추종 · 미국 상장 예시',title:'여러 기업을 담아도 구성과 비용을 확인하기',date:'2026년 SEC 제출 투자설명서 · 확인일 2026.09.21',source:'https://www.sec.gov/Archives/edgar/data/36405/000003640526000183/f44783d1.htm',sourceName:'Vanguard S&P 500 ETF 투자설명서',metrics:[['대표 학습 상품','VOO','Vanguard S&P 500 ETF'],['추종 대상','S&P 500','미국 대형주 지수'],['연간 총 운용비용','0.03%','투자설명서 기준']],fact:'VOO는 미국 대형주 지수의 성과를 추종하는 ETF 예시입니다. 지수 그 자체와 실제 매수할 수 있는 ETF는 구분해야 합니다.',interpret:'학습 관점: 개별 기업의 생존과 경쟁력 대신 지수의 구성 방식, 상위 종목 집중, 업종 비중, 비용과 추적 결과를 살펴봅니다. 종목 수만으로 위험이 사라지는 것은 아닙니다.',workedTitle:'운용비용을 금액으로 이해하기',worked:'1년 평균 투자금액을 10,000달러로 고정한다고 가정하면 10,000 × 0.0003 = 약 3달러입니다. 운용비용의 단순 예제이며 매매 수수료·스프레드·세금·환전 비용은 별도입니다. 실제 금액은 자산 가치에 따라 달라집니다.',checks:[['최신 구성과 비중','운용사 보유종목 자료의 기준일과 상위 종목 비중을 봅니다. 같은 지수를 담은 ETF를 여러 개 사는 것이 새로운 분산은 아닐 수 있습니다.'],['추적 결과','같은 기간·같은 배당 재투자 기준으로 ETF 순자산가치 수익률과 지수 수익률을 비교합니다.'],['거래와 환율','매수·매도 호가 차이와 순자산가치 대비 가격을 확인합니다. 원화 투자자는 환율 영향도 구분합니다.']],risk:'미국 주식시장 전체 하락과 대형 종목 집중에 노출될 수 있습니다. 미국 대형주 지수는 세계 주식 전체나 모든 자산을 포함하지 않습니다.',next:'보유 ETF의 정확한 티커·상장 시장·지수·환헤지 여부를 확인하고 최신 상위 보유 종목 읽기.',q:'같은 S&P 500 지수를 추종하는 ETF 두 개를 사면?',options:['기초자산이 겹칠 수 있다','반드시 위험이 절반으로 줄어든다','서로 완전히 다른 시장에 투자한다'],correct:0,answer:'상품 이름이 달라도 기초자산이 비슷할 수 있습니다. 실제 구성 종목과 비중으로 확인합니다.'},
{id:'qqqm',ticker:'QQQM',name:'나스닥 100 ETF',type:'지수 추종 · 미국 상장 예시',title:'100개 기업보다 중요한 것은 각 기업의 비중',date:'Invesco 팩트시트 · 2026.06.30 기준',source:'https://www.invesco.com/us-rest/contentdetail?contentId=5b4d8e58e0737710VgnVCM1000006e36b50aRCRD&dnsName=us',sourceName:'Invesco QQQM 공식 팩트시트',metrics:[['대표 학습 상품','QQQM','Invesco NASDAQ 100 ETF'],['총보수율','0.15%','2026.06.30 자료 기준'],['NVDA 편입 비중','7.60%','같은 기준일 · 현재 비중 아님']],fact:'나스닥 100은 나스닥 상장 대형 비금융 기업을 대상으로 하는 지수입니다. 나스닥 종합지수와 다릅니다. 이 자료의 QQQM 총보수율은 0.15%입니다.',interpret:'학습 관점: 지수 이름만 보기보다 특정 기업과 산업에 얼마나 집중되어 있는지 확인합니다. 엔비디아 직접 보유분과 ETF 안의 엔비디아를 합쳐 생각하는 연습이 유용합니다.',workedTitle:'직접 보유와 ETF 간접 보유 합치기',worked:'가상 포트폴리오에서 NVDA 직접 보유가 20%, QQQM이 50%라면, 위 기준일의 편입 비중을 적용한 두 경로 노출은 20 + 50 × 0.076 = 23.8%입니다. 나머지 30%에도 NVDA가 들어 있다면 추가 계산해야 합니다.',checks:[['보유종목 기준일','편입 비중은 변합니다. 최신 운용사 자료로 직접 보유 종목과 겹치는 비중을 확인합니다.'],['집중과 분산','ETF 개수보다 실제 기업·업종·위험 요인의 겹침을 봅니다. S&P 500 ETF와도 구성 종목이 겹칠 수 있습니다.'],['상품 구조','같은 지수 이름이라도 레버리지·인버스·커버드콜 상품은 수익 구조가 다릅니다. 일반 지수 추종 ETF와 구분합니다.']],risk:'특정 성장기업·산업에 대한 집중이 변동성을 키울 수 있습니다. 보유 종목 수가 많다는 이유만으로 광범위한 시장 분산과 같다고 볼 수 없습니다.',next:'현재 보유 상품의 운용사 구성표에서 NVDA 비중과 기준일을 찾아 아래 계산기에 입력하기.',q:'NVDA 20% + QQQM 50%, ETF 내 NVDA 7.6%라면 두 경로의 NVDA 노출은?',options:['20%','23.8%','70%'],correct:1,answer:'직접 비중 20%에 ETF를 통한 간접 비중 3.8%를 더합니다. 다른 보유 자산의 노출은 별도입니다.'}
];
let activeCase='ionq';
function cases(){const c=caseStudies.find(x=>x.id===activeCase);return head('실제 종목으로 배우는 분석','아이온큐 · 엔비디아 · S&P 500 · 나스닥 100. 같은 기준으로 모든 자산을 평가하지 않는 연습입니다.')+`<div class="note-banner">학습용 사례 · 자료 확인 2026.09.21 · 실시간 데이터나 매수·매도 추천이 아닙니다. ETF는 미국 상장 VOO·QQQM을 예시로 선택했으며 실제 보유 상품으로 가정하지 않습니다.</div><div class="topic-chips" aria-label="분석 사례 선택">${caseStudies.map(s=>`<button class="chip ${s.id===c.id?'selected':''}" data-case="${s.id}" aria-pressed="${s.id===c.id}">${s.name} · ${s.ticker}</button>`).join('')}</div><section class="panel"><span class="tag">${c.ticker} · ${c.type}</span><h2 style="margin:9px 0">${c.title}</h2><p class="note">${c.date}</p><div class="case-metrics">${c.metrics.map(([label,value,detail])=>`<div><span class="note">${label}</span><strong>${value}</strong><small>${detail}</small></div>`).join('')}</div><p class="note">M = 백만 달러. 금액은 미국 달러 기준입니다.</p><a class="source-link" href="${c.source}" target="_blank" rel="noopener noreferrer">숫자 원문 확인 · ${c.sourceName} ↗</a></section><div class="two-col" style="margin-top:22px"><section class="panel"><span class="tag">01 · 확인된 내용</span><h3 style="margin-top:10px">발표 자료에서 읽은 사실</h3><p>${c.fact}</p><span class="note">출처: 위 공식 원문 · 기준일 이후 변경 가능</span></section><section class="panel"><span class="tag">02 · 앱의 학습 해석</span><h3 style="margin-top:10px">어떤 질문으로 이어질까?</h3><p>${c.interpret}</p></section></div><section class="panel case-worked"><span class="tag">03 · 따라 계산하기</span><h3 style="margin-top:10px">${c.workedTitle}</h3><p>${c.worked}</p></section><div class="section-title"><h2>다음에 확인할 세 가지</h2></div><div class="course-grid">${c.checks.map(([t,d],i)=>`<article class="panel"><span class="tag">CHECK 0${i+1}</span><h3 style="margin-top:10px">${t}</h3><p class="note">${d}</p></article>`).join('')}</div><section class="panel" style="margin-top:22px"><h3>가설이 틀릴 수 있는 조건</h3><p>${c.risk}</p><h3>다음 실적·자료에서 할 일</h3><p>${c.next}</p><div class="actions"><button class="secondary" id="caseExport">이 사례의 분석 연습지 내려받기 ↓</button><button class="primary" data-go="notebook">내 분석 노트 열기 →</button></div><p class="note" style="margin-top:12px">연습지는 텍스트 파일입니다. 기존 분석 노트를 덮어쓰지 않습니다.</p></section><section class="panel" style="margin-top:22px"><span class="tag">CHECK YOUR UNDERSTANDING</span><h3 style="margin-top:10px">${c.q}</h3>${c.options.map((t,i)=>`<button class="answer" data-case-answer="${i}">${t}</button>`).join('')}<p id="caseFeedback" class="feedback" aria-live="polite"></p></section>${overlapPanel()}<section class="panel" style="margin-top:22px"><h3>개별주와 지수 ETF, 질문의 차이</h3><div class="report-map"><div><strong>개별주</strong><p class="note">사업이 성장하는가? 이익·현금·주식 수는? 현재 가격이 요구하는 성장은?</p></div><div><strong>지수 ETF</strong><p class="note">무슨 지수를 어떤 방식으로 추종하는가? 비용·구성·집중도·추적 결과는?</p></div></div><p class="note">한국 상장 지수 ETF를 사용한다면 정확한 상품명과 티커로 별도 확인하세요. 환헤지, 분배, 비용과 세금은 상장 시장·계좌에 따라 다를 수 있습니다.</p></section>`}
function overlapPanel(){return `<section class="panel" style="margin-top:22px"><span class="tag">EXPERIMENT · 가상 포트폴리오</span><h2>엔비디아 노출, 얼마나 겹칠까요?</h2><p class="note">초깃값은 가정입니다. 사용자의 실제 보유 비중이 아닙니다. ETF 내 비중 7.6%만 2026.06.30 QQQM 자료를 참고했습니다. 입력은 저장·전송하지 않습니다.</p><div class="case-metrics"><label class="field">NVDA 직접 비중 (%)<input id="directWeight" type="number" min="0" max="100" step="0.1" value="20"></label><label class="field">해당 ETF 비중 (%)<input id="etfWeight" type="number" min="0" max="100" step="0.1" value="50"></label><label class="field">ETF 안의 NVDA (%)<input id="insideWeight" type="number" min="0" max="100" step="0.1" value="7.6"></label></div><div id="overlapResult" class="calc-result" aria-live="polite"></div><p class="note" style="margin-top:12px">직접 비중 + ETF 비중 × ETF 내 NVDA 비중 ÷ 100. 다른 ETF·펀드·파생상품은 포함하지 않은 두 경로의 합계입니다.</p><a class="note" href="${caseStudies[3].source}" target="_blank" rel="noopener noreferrer">편입 비중의 과거 기준 자료 ↗</a></section>`}
function bindCases(){document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{activeCase=b.dataset.case;render()});const c=caseStudies.find(x=>x.id===activeCase);document.querySelectorAll('[data-case-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-case-answer]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');$('#caseFeedback').textContent=(+b.dataset.caseAnswer===c.correct?'맞았어요. ':'다시 생각해 보세요. ')+c.answer});$('#caseExport').onclick=()=>{const text=`LONGVIEW · ${c.name} 분석 연습지\n자료: ${c.date}\n원문: ${c.source}\n\n공식 수치\n${c.metrics.map(m=>m.join(' / ')).join('\n')}\n\n계산 연습\n${c.worked}\n\n내가 확인한 사실과 원문 위치:\n\n나의 해석과 가정:\n\n반대 증거:\n\n다음 확인할 질문:\n${c.next}\n\n확인 날짜:\n`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='longview-'+c.ticker+'-worksheet.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};['directWeight','etfWeight','insideWeight'].forEach(id=>$('#'+id).oninput=calculateOverlap);calculateOverlap()}
function calculateOverlap(){const vals=['directWeight','etfWeight','insideWeight'].map(id=>$('#'+id).value.trim()===''?NaN:Number($('#'+id).value));const [d,e,i]=vals;if(vals.some(v=>!Number.isFinite(v)||v<0||v>100)||d+e>100){$('#overlapResult').textContent='각 비중을 0~100%로 입력하고, 직접 보유와 ETF 보유의 합계는 100% 이하로 맞춰 주세요.';return}$('#overlapResult').innerHTML=`<span class="note">이 두 경로를 통한 NVDA 노출</span><div class="metric">${(d+e*i/100).toFixed(2)}%</div><span>직접 ${d}% + 간접 ${(e*i/100).toFixed(2)}% · 나머지 ${(100-d-e).toFixed(1)}%의 노출은 별도 확인</span>`}
